const stats = $input.first().json;
const totalQueries = stats.total_queries || 0;
const avgConfidence = stats.avg_confidence != null ? (stats.avg_confidence * 100).toFixed(1) : 'N/A';
const escalations = stats.escalations || 0;
const resolved = totalQueries - escalations;
const resolutionRate = totalQueries > 0 ? ((resolved / totalQueries) * 100).toFixed(1) : 'N/A';
const today = new Date().toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });
const message = '📊 FlowMind Daily Summary\n📅 ' + today + '\n\n🔍 Total Queries: ' + totalQueries + '\n✅ Resolved: ' + resolved + '\n🚨 Escalated: ' + escalations + '\n📈 Resolution Rate: ' + resolutionRate + '%\n🧠 Avg Confidence: ' + avgConfidence + '%\n📄 Total Documents: ' + (stats.total_documents || 0);
return [{ json: { message: message, totalQueries: totalQueries, escalations: escalations, avgConfidence: avgConfidence, date: today } }];
